import{_ as e,a as r,b as l,c as t,d as s,e as o,f as n,g as c,h as d,i as h,j as p}from"./chunks/power.BtpUPTqz.js";import{_ as u,C as m,o as g,c as f,E as _,a2 as b}from"./chunks/framework.CsGzzEsd.js";const j=JSON.parse('{"title":"飓风海伦影响评估","description":"","frontmatter":{"pageClass":"project-case-study","title":"飓风海伦影响评估","order":1},"headers":[],"relativePath":"zh/projects/NCCP.md","filePath":"zh/projects/NCCP.md"}'),q={name:"zh/projects/NCCP.md"};function P(v,a,k,C,x,N){const i=m("ProjectHero");return g(),f("div",null,[_(i,{index:"01",eyebrow:"城市分析 · 灾后恢复",title:"北卡罗来纳州西部飓风海伦影响评估",summary:"一项多来源评估，把风暴造成的实际损害与影响恢复进程的经济和社会条件联系起来。",year:"2024",role:"数据分析与研究",methods:"地理空间分析 · 公开数据 · 韧性指标",image:"/images/NCCP/precipitation.png","image-alt":"飓风海伦降水量与受灾县份地图",report:"/NCCP_slides.pdf"}),a[0]||(a[0]=b('<h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本项目评估飓风海伦对北卡罗来纳州西部的影响，内容包括风暴影响的总体分析、受灾县份排名、飓风前的状况，以及恢复和未来韧性建设的关键考量。</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>分析综合了多个权威来源的数据，包括 NOAA、美国国家气象局（NWS）、北卡州立气候办公室、Duke Energy、北卡林业局和北卡农业部。我们核实了受灾区域，并利用人口普查和北卡商务部的数据做了回溯研究。</p><h2 id="影响概要" tabindex="-1">影响概要 <a class="header-anchor" href="#影响概要" aria-label="Permalink to &quot;影响概要&quot;">​</a></h2><ul><li><strong>受灾最严重的县：</strong> Buncombe、McDowell、Henderson、Rutherford、Transylvania、Polk、Yancey、Mitchell、Avery</li><li><strong>损害类型：</strong><ul><li><strong>电力损害：</strong> 基础设施严重受损，并识别出修复难度较高的区域。</li><li><strong>森林损害：</strong> 六个县受损最重，尤其是 McDowell（130,805 英亩）和 Buncombe（89,440 英亩）。</li><li><strong>洪水与山体滑坡：</strong> 尤其集中在 Yancey、Avery 和 McDowell 县。</li></ul></li></ul><h2 id="回溯分析" tabindex="-1">回溯分析 <a class="header-anchor" href="#回溯分析" aria-label="Permalink to &quot;回溯分析&quot;">​</a></h2><p>飓风来临前，各县的韧性水平因以下因素而不同：</p><ul><li><strong>人口结构：</strong> 部分县租房者比例高、人口老龄化。</li><li><strong>收入与贫困趋势：</strong> 收入增长率和贫困下降的走势参差不齐。</li><li><strong>住房指标：</strong> 若干县房价增长缓慢、租金负担沉重。</li><li><strong>企业构成：</strong> 在 Mitchell 和 Yancey 等重灾区，小企业（年销售额低于 50 万美元）占比高，显示出脆弱性。</li></ul><h2 id="对企业的影响" tabindex="-1">对企业的影响 <a class="header-anchor" href="#对企业的影响" aria-label="Permalink to &quot;对企业的影响&quot;">​</a></h2><ul><li>按规模和地理集中度绘制了企业分布图。</li><li>小企业占比高的地区被视为韧性较弱。</li><li>基础设施损毁和停电对小企业冲击很大，在农村和山区尤其明显。</li></ul><h2 id="后续考量" tabindex="-1">后续考量 <a class="header-anchor" href="#后续考量" aria-label="Permalink to &quot;后续考量&quot;">​</a></h2><ol><li><strong>数据建设：</strong> 补充基础设施韧性、经济健康度、空置率以及飓风后的人口迁移数据。</li><li><strong>项目梳理：</strong> 梳理可用的联邦、州和地方资助项目。</li><li><strong>战略行动：</strong><ul><li>支持弱势群体。</li><li>振兴本地企业。</li><li>提升应对未来灾害的韧性。</li><li>实施反欺诈措施。</li></ul></li></ol><hr><h2 id="影响概要-1" tabindex="-1">影响概要 <a class="header-anchor" href="#影响概要-1" aria-label="Permalink to &quot;影响概要&quot;">​</a></h2><div class="figure"><img src="'+e+'" alt="受灾最严重县份地图"><p class="caption">受灾最严重的县份，以及修复复杂区与灾后重建区。</p></div><h2 id="回溯分析-1" tabindex="-1">回溯分析 <a class="header-anchor" href="#回溯分析-1" aria-label="Permalink to &quot;回溯分析&quot;">​</a></h2><div class="figure"><img src="'+r+'" alt="住房比例分析"><p class="caption">各县的自有房与租房比例、房价增长和租金负担。</p></div><h2 id="对企业的影响-1" tabindex="-1">对企业的影响 <a class="header-anchor" href="#对企业的影响-1" aria-label="Permalink to &quot;对企业的影响&quot;">​</a></h2><div class="figure"><img src="'+l+'" alt="小企业与大企业分布"><p class="caption">小企业与大企业的分布及其对韧性的影响。</p></div><h2 id="后续考量-1" tabindex="-1">后续考量 <a class="header-anchor" href="#后续考量-1" aria-label="Permalink to &quot;后续考量&quot;">​</a></h2><div class="figure"><img src="'+t+'" alt="后续恢复框架"><p class="caption">总结飓风后政策与资助举措关键考量的框架。</p></div><h2 id="森林损害概览" tabindex="-1">森林损害概览 <a class="header-anchor" href="#森林损害概览" aria-label="Permalink to &quot;森林损害概览&quot;">​</a></h2><div class="figure"><img src="'+s+'" alt="森林损害概览"><p class="caption">各受灾县的森林损害区域。</p></div><h2 id="森林损害详情" tabindex="-1">森林损害详情 <a class="header-anchor" href="#森林损害详情" aria-label="Permalink to &quot;森林损害详情&quot;">​</a></h2><div class="figure"><img src="'+o+'" alt="森林损害详情"><p class="caption">北卡西部森林损害的详细分解。</p></div><h2 id="房价增长" tabindex="-1">房价增长 <a class="header-anchor" href="#房价增长" aria-label="Permalink to &quot;房价增长&quot;">​</a></h2><div class="figure"><img src="'+n+'" alt="房价增长"><p class="caption">各县房价增长趋势。</p></div><h2 id="房价与收入的差距" tabindex="-1">房价与收入的差距 <a class="header-anchor" href="#房价与收入的差距" aria-label="Permalink to &quot;房价与收入的差距&quot;">​</a></h2><div class="figure"><img src="'+c+'" alt="房价差距"><p class="caption">房价与收入中位数之间的差距。</p></div><h2 id="租金负担" tabindex="-1">租金负担 <a class="header-anchor" href="#租金负担" aria-label="Permalink to &quot;租金负担&quot;">​</a></h2><div class="figure"><img src="'+d+'" alt="租金负担图"><p class="caption">面临高租金负担的人口比例。</p></div><h2 id="大企业分布" tabindex="-1">大企业分布 <a class="header-anchor" href="#大企业分布" aria-label="Permalink to &quot;大企业分布&quot;">​</a></h2><div class="figure"><img src="'+h+'" alt="大企业分布"><p class="caption">各受灾县的大企业分布。</p></div><h2 id="电力基础设施损害" tabindex="-1">电力基础设施损害 <a class="header-anchor" href="#电力基础设施损害" aria-label="Permalink to &quot;电力基础设施损害&quot;">​</a></h2><div class="figure"><img src="'+p+'" alt="电力基础设施损害"><p class="caption">电力基础设施受损区域地图。</p></div><h2 id="原始幻灯片-英文" tabindex="-1">原始幻灯片（英文） <a class="header-anchor" href="#原始幻灯片-英文" aria-label="Permalink to &quot;原始幻灯片（英文）&quot;">​</a></h2><div class="pdf-embed"><iframe src="/NCCP_slides.pdf#zoom=fitW" type="application/pdf" width="80%" height="800" style="border:none;overflow:hidden;"></iframe><div class="pdf-embed-fallback"><p>当前视图无法预览 PDF，请下载查看：</p><p><a href="/NCCP_slides.pdf" target="_blank" download>📥 下载幻灯片</a></p></div></div><p><a href="/NCCP_slides.pdf" target="_blank" download="">📥 下载报告</a></p>',39))])}const A=u(q,[["render",P]]);export{j as __pageData,A as default};
